style.css:
/* Body - Black Background for AMOLED */
body {
  background-color: #000000;
  color: #001eff; /*(Neon Blue): A bright, electric blue */
  font-family: 'hacker', Tahoma, Geneva, Verdana, sans-serif; /* Example font */
}

/* Headings - Brighter to stand out */
h1, h2, h3, h4, h5, h6 {
  color: #00ff00; /* Razer Green - Razer inspired, stands out on black */
}

/* Links - Distinguishable but not relying on color alone */
a {
  color: #06cf13; /* Vivid Malachite - distinguishable and high contrast */
  text-decoration: underline; /* Add underline for non-color cues */
}

/* Interactive elements (buttons) - Clear contrast and hover effects */
button {
  background-color: #0c6c12; /* Deep Green - Razer inspired */
  color: #ffffff; /* White text for clear contrast */
  border: 1px solid #00ff00; /* Razer Green border */
  padding: 10px 15px;
  border-radius: 5px;
  cursor: pointer;
}
